import _CryptoExtras
import Foundation
import SwiftASN1
import Testing
import X509

enum CertificateFixtures {
    static let privateKeyPEMBase64 =
        ""

    static let certificateDERBase64 =
        ""

    static func privateKey() throws -> _RSA.Signing.PrivateKey {
        let encoded = try #require(Data(base64Encoded: privateKeyPEMBase64))
        let pem = try #require(String(data: encoded, encoding: .utf8))
        return try _RSA.Signing.PrivateKey(pemRepresentation: pem)
    }

    static func certificateDER() throws -> Data {
        try #require(Data(base64Encoded: certificateDERBase64))
    }

    static func certificate() throws -> X509.Certificate {
        try X509.Certificate(derEncoded: Array(certificateDER()))
    }
}
